import assert from 'node:assert/strict';
import mime from '../../dist/src/index.js';

// A file name holding a line feed must still be typed by the extension after its last dot.
assert.equal(mime.getType('LINE\nFEED.png'), 'image/png');
assert.equal(mime.getType('/path/to/LINE\nFEED.png'), 'image/png');

// Ordinary names are unchanged.
assert.equal(mime.getType('report.html'), 'text/html');
assert.equal(mime.getType('/path/to/.config.json'), 'application/json');
assert.equal(mime.getType('/path/to/file'), null);

console.log('visible check passed');

import { readFileSync } from 'node:fs';
import assert from 'node:assert/strict';
import { Deflate, Inflate, deflate, inflate } from '../../src/index.ts';

const inflateSource = readFileSync(new URL('../../src/inflate.ts', import.meta.url), 'utf8');
const deflateSource = readFileSync(new URL('../../src/deflate.ts', import.meta.url), 'utf8');

// The fallbacks are gone from both files.
assert.equal((inflateSource.match(/options \|\| \{\}/g) ?? []).length, 0, 'inflate.ts still has `options || {}`');
assert.equal((deflateSource.match(/options \|\| \{\}/g) ?? []).length, 0, 'deflate.ts still has `options || {}`');

// Behaviour is unchanged with and without options.
const data = new TextEncoder().encode('pako default options');
assert.equal(new TextDecoder().decode(inflate(deflate(data))), 'pako default options');
assert.equal(inflate(deflate(data), { toText: true }), 'pako default options');
const d = new Deflate();
d.push(data, true);
const i = new Inflate();
i.push(d.result, true);
assert.equal(new TextDecoder().decode(i.result), 'pako default options');

console.log('visible check passed');
